class profile(_KinetoProfile):
    def __init__(
        self,
        *,
        activities: Optional[Iterable[ProfilerActivity]] = None,
        schedule: Optional[Callable[[int], ProfilerAction]] = None,
        on_trace_ready: Optional[Callable[..., Any]] = None,
        record_shapes: bool = False,
        profile_memory: bool = False,
        with_stack: bool = False,
        with_flops: bool = False,
        with_modules: bool = False,
        experimental_config: Optional[_ExperimentalConfig] = None,
        custom_trace_id_callback: Optional[Callable[[], str]] = None,
        # deprecated:
        use_cuda: Optional[bool] = None,
    ):
        super().__init__(
            activities=activities,
            record_shapes=record_shapes,
            profile_memory=profile_memory,
            with_stack=with_stack,
            with_flops=with_flops,
            with_modules=with_modules,
            experimental_config=experimental_config,
        )
        activities_set = set(activities) if activities else supported_activities()
        if schedule and isinstance(schedule, Callable):
            self.schedule = schedule
            # add step markers into the trace and table view
            self.record_steps = True
        else:
            if schedule:
                print_warn_msg("schedule is not Callable, set by default.")
            self.schedule = _default_schedule_fn
            self.record_steps = False
        if on_trace_ready and not isinstance(on_trace_ready, Callable):
            print_warn_msg("on_trace_ready is not Callable, set by default.")
            on_trace_ready = None
        self.prof_if = _ProfInterface(
            activities=activities_set,
            record_shapes=record_shapes,
            profile_memory=profile_memory,
            with_stack=with_stack,
            with_flops=with_flops,
            with_modules=with_modules,
            experimental_config=experimental_config,
            schedule=self.schedule,
            metadata=self.metadata,
            custom_trace_id_callback=custom_trace_id_callback,
        )
        self.on_trace_ready = on_trace_ready
        self.step_num = 0
        self.current_action = self.schedule(self.step_num)
        self._step_num_offset = 0
        self.step_rec_fn: Optional[prof.record_function] = None
        self._step_mstx_range_id = 0
        self._is_dynamic_prof = False
        if use_cuda is not None:
            print_warn_msg("This is npu environment, use_cuda is invalid")
        self.stopped = False
        self.action_controller = ProfActionController(
            self, self.prof_if, self.on_trace_ready
        )

    @no_exception_func()
    def __enter__(self):
        self.start()
        return self

    @no_exception_func()
    def __exit__(self, exe_type, exe_val, exc_tb):
        self.stop()

    @no_exception_func()
    def __del__(self):
        if not self.stopped:
            self.stop()

    @no_exception_func()
    def _set_step_num_offset_for_dynamic_prof(self, step: int):
        self._step_num_offset = step
        self._is_dynamic_prof = True

    def _start_step_mstx_range(self, message: str):
        if not self._is_dynamic_prof:
            self._step_mstx_range_id = mstx.range_start(message, current_stream())

    def _end_step_mstx_range(self):
        if self._is_dynamic_prof or not self._step_mstx_range_id:
            return
        mstx.range_end(self._step_mstx_range_id)
        self._step_mstx_range_id = 0

    @no_exception_func()
    def start(self):
        self.stopped = False
        if not self.on_trace_ready:
            ProfPathCreator().init(export_only_mode=True)
        self.action_controller.transit_action(ProfilerAction.NONE, self.current_action)
        if self.record_steps:
            step_name = "ProfilerStep#" + str(self.step_num + self._step_num_offset)
            self.step_rec_fn = prof.record_function(step_name)
            self.step_rec_fn.__enter__()
            self._start_step_mstx_range(step_name)

    @no_exception_func()
    def stop(self):
        if self.record_steps and self.step_rec_fn:
            self.step_rec_fn.__exit__(None, None, None)
            self._end_step_mstx_range()
        self.action_controller.transit_action(self.current_action, None)
        self.stopped = True

    @no_exception_func()
    def step(self):
        if self.stopped:
            print_warn_msg("Profiler is stopped, step takes no effect!")
            return
        if self.record_steps and self.step_rec_fn:
            self.step_rec_fn.__exit__(None, None, None)
            self._end_step_mstx_range()
        prev_action = self.current_action
        self.step_num += 1
        self.current_action = self.schedule(self.step_num)
        self.action_controller.transit_action(prev_action, self.current_action)
        if self.record_steps:
            step_name = "ProfilerStep#" + str(self.step_num + self._step_num_offset)
            self.step_rec_fn = prof.record_function(step_name)
            self.step_rec_fn.__enter__()
            self._start_step_mstx_range(step_name)

    @no_exception_func()
    def set_custom_trace_id_callback(self, callback: Callable[[], str]) -> None:
        self.prof_if.custom_trace_id_callback = callback

    @no_exception_func()
    def get_trace_id(self) -> str:
        return self.prof_if.trace_id

    @classmethod
    @no_exception_func()
    def enable_profiler_in_child_thread(
        cls,
        record_shapes: bool = False,
        profile_memory: bool = False,
        with_stack: bool = False,
        with_flops: bool = False,
        with_modules: bool = False,
    ):
        params = {
            "record_shapes": record_shapes,
            "profile_memory": profile_memory,
            "with_stack": with_stack,
            "with_flops": with_flops,
            "with_modules": with_modules,
        }
        for param_name, param_value in params.items():
            if not isinstance(param_value, bool):
                print_warn_msg(
                    f"{param_name} in enable_profiler_in_child_thread is not bool, reset it to False."
                )
                params[param_name] = False
        npu_prof_config = NpuProfilerConfig(
            "",
            params["record_shapes"],
            params["profile_memory"],
            params["with_stack"],
            params["with_flops"],
            params["with_modules"],
            C_ExperimentalConfig(),
        )
        _enable_profiler_in_child_thread(npu_prof_config)

    @classmethod
    @no_exception_func()
    def disable_profiler_in_child_thread(cls):
        torch_npu.npu.synchronize()
        _disable_profiler_in_child_thread()

